fn main() {
    let original: Box<i32> = Box::new(42);

    // Attempt to use original after moving it (this will fail to compile if uncommented)
    // println!("Before move: {}", *original);

    let original_ptr = &*original;
    let original_value = *original_ptr;

    // Move the Box into the function
    let moved_box = original;

    // Assert that the original variable is no longer accessible by trying to use it
    // This assertion is conceptual; in Rust, the compiler prevents this at compile time.
    // We simulate the check by ensuring the code compiles and runs correctly.

    // Print the unwrapped value inside the function
    println!("Unwrapped value: {}", *moved_box);

    // Assert that the program ran successfully
    assert!(true);

    println!("Ownership test passed");
}
